def share_mana_discovery(iterator):
    iterator = iter(iterator)
    try:
        while True:
            with mana_discovery_scope():
                try:
                    option = next(iterator)
                except StopIteration:
                    return
            yield option
    finally:
        close = getattr(iterator, "close", None)
        if close is not None:
            close()

