@contextmanager
def mana_discovery_scope():
    existing = _CURRENT.get()
    if existing is not None:
        yield existing
        return
    token = _CURRENT.set(ManaDiscoveryContext())
    try:
        yield _CURRENT.get()
    finally:
        _CURRENT.reset(token)
